import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialMin, uint256 newMin, uint256 lockTime, uint256 deposit, uint256 collectAmt) public {
        vm.assume(initialMin > 0);
        vm.assume(newMin != initialMin);
        vm.assume(deposit > 0);
        vm.assume(collectAmt > 0);
        vm.assume(collectAmt <= deposit);
        vm.assume(lockTime < type(uint256).max - block.timestamp);

        // Deploy a re-entrant attacker that calls SetMinSum during Collect
        address attacker = address(new ReentrantAttacker(address(c), newMin));
        vm.deal(attacker, deposit + 1 ether);

        // Initialize c
        c.SetMinSum(initialMin);
        c.Initialized();

        // Fund and put via attacker
        vm.startPrank(attacker);
        c.Put{value: deposit}(lockTime);
        // Warp past unlock time
        vm.warp(block.timestamp + lockTime + 1);
        uint256 minSumBefore = c.MinSum();
        // Collect triggers re-entrant call that attempts to modify MinSum
        c.Collect(collectAmt);
        vm.stopPrank();

        uint256 minSumAfter = c.MinSum();
        assertTrue(minSumAfter == minSumBefore);
    }
}

